import{describe,it,expect}from"vitest";import{yieldComparisonData,pillarsOfRevolution,impactAnalysis,timelineEras,calculateYieldGrowth,getYieldDataByCrop,getImpactsByCategory,filterGreenRevolutionTopics}from"../../frontend/green-revolution/green-revolution.js";describe("Green Revolution Yield Comparison Dataset Integrity",()=>{it("contains yield comparison data for Wheat, Rice, Foodgrain Output, and Tubewell Irrigation",()=>{expect(yieldComparisonData.length).toBeGreaterThanOrEqual(4);const e=yieldComparisonData.map(e=>e.crop.toLowerCase());expect(e.some(e=>e.includes("wheat"))).toBe(!0),expect(e.some(e=>e.includes("rice"))).toBe(!0),expect(e.some(e=>e.includes("foodgrain"))).toBe(!0)}),it("every crop object contains pre-1960, post-1980, and modern 2020 yield figures",()=>{yieldComparisonData.forEach(e=>{expect(e).toHaveProperty("crop"),expect(e).toHaveProperty("unit"),expect(e).toHaveProperty("pre1960"),expect(e).toHaveProperty("post1980"),expect(e).toHaveProperty("modern2020"),expect(e).toHaveProperty("growthPercent"),expect(typeof e.pre1960).toBe("number"),expect(typeof e.post1980).toBe("number"),expect(typeof e.modern2020).toBe("number"),expect(e.post1980).toBeGreaterThan(e.pre1960)})}),it("correctly calculates yield growth percentage using helper function",()=>{const e=calculateYieldGrowth(850,1850);expect(e).toBe(118);const t=calculateYieldGrowth(1e3,2700);expect(t).toBe(170),expect(calculateYieldGrowth(0,100)).toBe(0)})}),describe("Balanced Impact Analysis (Benefits vs Ecological Drawbacks)",()=>{it("contains documented positive benefits AND documented ecological/social drawbacks",()=>{expect(impactAnalysis.benefits.length).toBeGreaterThanOrEqual(3),expect(impactAnalysis.drawbacks.length).toBeGreaterThanOrEqual(4)}),it("documented drawbacks cover groundwater depletion, soil salinization, and crop diversity loss",()=>{const e=impactAnalysis.drawbacks.map(e=>e.summary.toLowerCase()+" "+e.title.toLowerCase());expect(e.some(e=>e.includes("groundwater")||e.includes("water table"))).toBe(!0),expect(e.some(e=>e.includes("soil")||e.includes("salinization"))).toBe(!0),expect(e.some(e=>e.includes("diversity")||e.includes("monoculture")||e.includes("millet"))).toBe(!0)}),it("retrieves impacts by category using helper function",()=>{const e=getImpactsByCategory("benefits");expect(e.length).toBeGreaterThanOrEqual(3);const t=getImpactsByCategory("drawbacks");expect(t.length).toBeGreaterThanOrEqual(4)})}),describe("Technological Pillars & Timeline Integrity",()=>{it("contains 4 core technological pillars of the Green Revolution",()=>{expect(pillarsOfRevolution.length).toBe(4),pillarsOfRevolution.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("keyFigures"),expect(e).toHaveProperty("description"),expect(e).toHaveProperty("techDetails")})}),it("contains timeline phases spanning 1965 to Present",()=>{expect(timelineEras.length).toBeGreaterThanOrEqual(4),expect(timelineEras[0].year).toContain("1965")})}),describe("Search & Topic Filter Helper",()=>{it("filters Green Revolution topics by search query (e.g. Groundwater or Wheat)",()=>{const e=filterGreenRevolutionTopics("Groundwater");expect(e.drawbacks.length).toBeGreaterThan(0);const t=filterGreenRevolutionTopics("Wheat");expect(t.yields.length).toBeGreaterThan(0)}),it("returns full dataset when search query is empty",()=>{const e=filterGreenRevolutionTopics("");expect(e.yields.length).toBe(yieldComparisonData.length),expect(e.pillars.length).toBe(pillarsOfRevolution.length)})});